// Inlines src/page/page.css and src/page/page.js into src/page/page.html,
// computes the SHA-256 hashes the Content-Security-Policy needs to allow
// exactly that script and style, and writes src/page.generated.ts.
//
// The generated file is committed so the deployed page can be reviewed in the
// repo; CI rebuilds it and fails if it differs.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");

const template = read("src/page/page.html");
const style = read("src/page/page.css");
const script = read("src/page/page.js");

const hash = (source: string) => `'sha256-${createHash("sha256").update(source, "utf8").digest("base64")}'`;

const directives = [
	"default-src 'none'",
	`script-src ${hash(script)}`,
	`style-src ${hash(style)}`,
	"img-src data:",
	"connect-src 'none'",
	"form-action 'none'",
	"base-uri 'none'",
];

// frame-ancestors only works as a header; browsers ignore it (with a console
// warning) in a <meta> tag, so the meta policy leaves it out.
const metaPolicy = directives.join("; ");
const headerPolicy = [...directives, "frame-ancestors 'none'"].join("; ");

for (const placeholder of ["{{CSP}}", "{{STYLE}}", "{{SCRIPT}}"]) {
	if (template.split(placeholder).length !== 2) {
		throw new Error(`page.html must contain ${placeholder} exactly once`);
	}
}

// Replace with functions so "$" sequences in the sources are left alone.
const html = template
	.replace("{{CSP}}", () => metaPolicy)
	.replace("{{STYLE}}", () => style)
	.replace("{{SCRIPT}}", () => script);

const output = `// Generated by scripts/build-page.ts from src/page/. Do not edit.

export const PAGE_CSP = ${JSON.stringify(headerPolicy)};

export const PAGE_HTML = ${JSON.stringify(html)};
`;

writeFileSync(new URL("src/page.generated.ts", root), output);
console.log("Wrote src/page.generated.ts");
